from griffe import Extension, load_extensions, load


class CheckedExtension(Extension):
    """Extension that appends ' [checked]' to function docstrings."""

    def on_function(self, *, func, loader, **kwargs):
        if func.docstring:
            func.docstring.value += " [checked]"
        else:
            func.docstring = type(func.docstring)(value=" [checked]") if func.docstring else None


extensions = load_extensions(CheckedExtension())
module = load("mypkg", extensions=extensions)

